import { useCallback, useEffect, useState, type FormEvent, type ReactNode } from 'react';
import { Link, useSearchParams } from 'react-router-dom';
import { ArrowRight, CalendarDays, Check, ChevronRight, Clock3, Download, Heart, Leaf, LogOut, MapPin, Medal, Menu, Plus, Settings2, ShieldCheck, Sparkles, Users, X } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Progress } from '@/components/ui/progress';
import { AttendanceQr } from '@/components/AttendanceQr';
import { toast } from 'sonner';

type User = { id: number; name: string; email: string; role: 'member'|'assistant'|'admin' };
type Event = { id: number; series_id: number; title: string; description: string; location: string; starts_at: string; ends_at: string; timezone: string; capacity: number; visibility: 'public'|'private'; canceled: number; registered: number; mine: number };
type Settings = { name: string; color: string; logo: string; initialized: boolean; mailMode?: string; smtpHost?: string; smtpPort?: string; smtpEncryption?: string; smtpUser?: string; smtpFrom?: string };
type Waiver = { id: number; version: number; text: string; signed: number };
type Bootstrap = { settings: Settings; user: User|null; events: Event[]; waiver: Waiver|null };
type Attendance = { event_id: number; user_id: number; title: string; name?: string; email?: string; check_in: string; check_out: string|null; method: string };
type MedalRow = { id: number; name: string; metric: 'events'|'hours'; threshold: number };
type MemberData = { user: User; registrations: Event[]; attendance: Attendance[]; metrics: { events: number; hours: number }; milestones: MedalRow[] };
type StaffData = { members: User[]; events: Event[]; attendance: Attendance[]; medals: MedalRow[]; waivers: Waiver[]; settings?: Settings };
const request = async <T,>(path: string, body?: unknown, method = 'POST'): Promise<T> => { const response = await fetch(path, { method: body === undefined && method === 'POST' ? 'GET' : method, credentials: 'same-origin', headers: { 'Content-Type': 'application/json', 'X-Requested-With': 'KindredHours' }, body: body === undefined ? undefined : JSON.stringify(body) }); const result = await response.json(); if (!response.ok) throw new Error(result.error || 'Something went wrong. Please try again.'); return result as T; };
const dateLabel = (date: string, timezone?: string) => new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit', timeZone: timezone || undefined }).format(new Date(date));
const zonedInput = (date: string, timezone: string) => { const parts = new Intl.DateTimeFormat('en-CA', { timeZone: timezone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }).formatToParts(new Date(date)); const get = (key: string) => parts.find(part => part.type === key)?.value; return `${get('year')}-${get('month')}-${get('day')}T${get('hour')}:${get('minute')}`; };
const Field = ({ label, children }: { label: string; children: ReactNode }) => <div className="space-y-2"><Label className="text-sm font-semibold text-forest">{label}</Label>{children}</div>;
const notice = (error: unknown) => toast.error(error instanceof Error ? error.message : 'Something went wrong.');
const initialSettings: Settings = { name: 'Kindred Hours', color: '#D7654F', logo: '', initialized: true };

export default function Index() {
  const [bootstrap, setBootstrap] = useState<Bootstrap>({ settings: initialSettings, user: null, events: [], waiver: null });
  const [loading, setLoading] = useState(true);
  const [offline, setOffline] = useState(false);
  const [page, setPage] = useState<'home'|'events'|'portal'|'staff'>('home');
  const [auth, setAuth] = useState<'login'|'register'|'forgot'|'password'|null>(null);
  const [searchParams, setSearchParams] = useSearchParams();
  const [mobileOpen, setMobileOpen] = useState(false);
  const [member, setMember] = useState<MemberData|null>(null);
  const [staff, setStaff] = useState<StaffData|null>(null);
  const [busy, setBusy] = useState(false);
  const [setupStep, setSetupStep] = useState(0);
  const [setupName, setSetupName] = useState('');
  const [setupColor, setSetupColor] = useState('#D7654F');
  const [setupAdmin, setSetupAdmin] = useState({ name: '', email: '', password: '' });
  const [authForm, setAuthForm] = useState({ name: '', email: '', password: '' });
  const [signature, setSignature] = useState('');
  const [eventForm, setEventForm] = useState({ title: '', description: '', location: '', startsAt: '', endsAt: '', timezone: Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC', capacity: '20', visibility: 'public', frequency: 'none', count: '4' });
  const [attendanceForm, setAttendanceForm] = useState({ eventId: '', userId: '', action: 'in', method: 'staff' });
  const [settingsForm, setSettingsForm] = useState({ name: '', color: '#D7654F', mailMode: 'file', smtpHost: '', smtpPort: '587', smtpEncryption: 'starttls', smtpUser: '', smtpPassword: '', smtpFrom: '' });
  const [waiverText, setWaiverText] = useState('');
  const [medalForm, setMedalForm] = useState({ name: '', metric: 'events', threshold: '5' });
  const [staffTab, setStaffTab] = useState<'overview'|'events'|'attendance'|'members'|'waivers'|'medals'|'settings'>('overview');
  const [editEvent, setEditEvent] = useState<Event|null>(null);
  const [editForm, setEditForm] = useState({ title: '', description: '', location: '', capacity: '', visibility: 'public', starts_at: '', ends_at: '', scope: 'single' });

  const refresh = useCallback(async () => { try { const data = await request<Bootstrap>('/api/bootstrap'); setBootstrap(data); setOffline(false); if (data.user) { const [m, s] = await Promise.all([request<MemberData>('/api/me'), ['admin','assistant'].includes(data.user.role) ? request<StaffData>('/api/staff') : Promise.resolve(null)]); setMember(m); setStaff(s); if (s?.settings) setSettingsForm(v => ({ ...v, ...s.settings, mailMode: s.settings?.mailMode || 'file', smtpPassword: '' })); } else { setMember(null); setStaff(null); } } catch { setOffline(true); } finally { setLoading(false); } }, []);
  useEffect(() => { void refresh(); }, [refresh]);
  useEffect(() => { if (searchParams.get('token')) setAuth('password'); }, [searchParams]);
  useEffect(() => { document.documentElement.style.setProperty('--brand', bootstrap.settings.color); }, [bootstrap.settings.color]);
  const act = async (fn: () => Promise<unknown>, message: string) => { setBusy(true); try { await fn(); toast.success(message); await refresh(); } catch (error) { notice(error); } finally { setBusy(false); } };
  const submitAuth = async (e: FormEvent) => { e.preventDefault(); if (!auth) return; await act(async () => { if (auth === 'password') { await request('/api/password', { token: searchParams.get('token'), action: searchParams.get('action'), password: authForm.password }); setSearchParams({}); } else await request(`/api/${auth === 'register' ? 'register' : auth === 'forgot' ? 'forgot' : 'login'}`, auth === 'register' ? authForm : { email: authForm.email, ...(auth === 'login' ? { password: authForm.password } : {}) }); setAuth(null); setAuthForm({ name: '', email: '', password: '' }); }, auth === 'login' || auth === 'password' ? 'Welcome back!' : 'If the address is eligible, check your email.'); };
  const submitSetup = (e: FormEvent) => { e.preventDefault(); void act(async () => { await request('/api/setup', { name: setupName, color: setupColor, adminName: setupAdmin.name, email: setupAdmin.email, password: setupAdmin.password }); setPage('staff'); }, 'Your organization is ready.'); };
  const navigate = (target: typeof page) => { setPage(target); setMobileOpen(false); window.scrollTo({ top: 0, behavior: 'smooth' }); };
  const showEdit = (e: Event) => { setEditEvent(e); setEditForm({ title: e.title, description: e.description, location: e.location, capacity: String(e.capacity), visibility: e.visibility, starts_at: zonedInput(e.starts_at, e.timezone), ends_at: zonedInput(e.ends_at, e.timezone), scope: 'single' }); };
  const eventCard = (event: Event) => <article key={event.id} className="group overflow-hidden rounded-[26px] border border-[#e7e6db] bg-white shadow-[0_12px_32px_-26px_rgba(22,68,53,.32)] transition-transform hover:-translate-y-1">
    <div className="flex h-44 items-end justify-between bg-[#e6eee5] p-5" style={{ backgroundImage: 'url(/assets/community-garden.png)', backgroundSize: 'cover', backgroundPosition: 'center 42%' }}><span className="rounded-full bg-white/95 px-3 py-1 text-xs font-bold uppercase tracking-wider text-forest">{event.visibility === 'private' ? 'Members only' : 'Open to all'}</span><span className="rounded-full bg-white/95 px-3 py-1 text-xs font-semibold text-forest">{Math.max(0,event.capacity-event.registered)} spots left</span></div>
    <div className="space-y-4 p-6"><div><h3 className="font-display text-2xl font-semibold text-forest">{event.title}</h3><p className="mt-2 line-clamp-2 text-sm leading-relaxed text-[#62746a]">{event.description}</p></div><div className="space-y-2 text-sm text-[#51675a]"><p className="flex items-center gap-2"><CalendarDays size={16} className="text-coral" />{dateLabel(event.starts_at,event.timezone)}</p><p className="flex items-center gap-2"><MapPin size={16} className="text-coral" />{event.location}</p><p className="flex items-center gap-2"><Clock3 size={16} className="text-coral" />Until {dateLabel(event.ends_at,event.timezone)} · {event.timezone}</p></div><div className="flex items-center justify-between border-t border-[#ebeee8] pt-4"><span className="text-xs text-[#6c7b70]">{event.registered} / {event.capacity} registered</span><Button disabled={busy} className={event.mine ? 'rounded-full bg-[#e5eee6] text-forest hover:bg-[#d4e5d6]' : 'rounded-full bg-coral text-white hover:bg-[#bd4d39]'} onClick={() => bootstrap.user ? void act(() => request(`/api/registrations${event.mine ? `/${event.id}` : ''}`, event.mine ? undefined : { eventId: event.id }, event.mine ? 'DELETE' : 'POST'), event.mine ? 'Registration canceled.' : 'You are registered!') : setAuth('register')}>{event.mine ? 'Cancel spot' : 'Join this event'} <ArrowRight size={15} className="ml-2" /></Button></div></div>
  </article>;
  if (loading) return <div className="flex min-h-screen items-center justify-center bg-cream font-display text-3xl text-forest">Kindred Hours <span className="ml-2 animate-pulse text-coral">✳</span></div>;
  if (!bootstrap.settings.initialized && !offline) return <main className="min-h-screen bg-cream px-5 py-10 text-forest"><div className="mx-auto max-w-3xl"><div className="mb-12 flex items-center gap-3"><BrandMark /><span className="font-display text-2xl font-bold">Kindred Hours</span></div><div className="mb-8 flex gap-3">{['Getting started','Your organization','Administrator'].map((step,i) => <div key={step} className={`flex-1 rounded-full px-3 py-2 text-center text-xs font-semibold sm:text-sm ${i === setupStep ? 'bg-forest text-white' : 'bg-white text-[#65776b]'}`}>{i+1}. {step}</div>)}</div><div className="rounded-[32px] border border-[#e5e8db] bg-white p-7 shadow-sm sm:p-12">{setupStep === 0 ? <><p className="eyebrow">Welcome, organizer</p><h1 className="mt-3 font-display text-4xl font-semibold">Let's build something good together.</h1><p className="mt-4 leading-7 text-[#637569]">This one-time setup creates your organization and its first administrator. No default account or password is provided.</p><div className="mt-8 rounded-2xl bg-[#f3f5ee] p-5"><p className="font-semibold">First, choose your host port</p><p className="mt-2 text-sm leading-6 text-[#607268]">Docker publishes the app's internal port 3000 through a port on your computer. Set <code className="rounded bg-white px-1">HOST_PORT</code> in your .env file before starting Compose. The browser cannot change or test a Docker port after the container starts. The installation guide explains how to verify the port is free.</p></div><Button className="mt-8 rounded-full bg-coral px-7 text-white" onClick={() => setSetupStep(1)}>Continue <ArrowRight className="ml-2 h-4 w-4" /></Button></> : setupStep === 1 ? <><p className="eyebrow">Step 02 / 03</p><h1 className="mt-3 font-display text-4xl font-semibold">Make it yours.</h1><div className="mt-8 grid gap-6"><Field label="Organization name"><Input value={setupName} onChange={e=>setSetupName(e.target.value)} maxLength={100} placeholder="e.g. The Neighborhood Project" className="rounded-xl" /></Field><Field label="Brand color"><div className="flex gap-3"><Input type="color" value={setupColor} onChange={e=>setSetupColor(e.target.value)} className="h-11 w-16 rounded-xl p-1" /><Input value={setupColor} onChange={e=>setSetupColor(e.target.value)} className="rounded-xl" /></div></Field><div className="rounded-2xl bg-[#f3f5ee] p-5 text-sm leading-6 text-[#607268]">Email starts in file mode. Account links and test messages are saved privately in the persistent volume. Configure SMTP and upload a logo under Administration → Settings after setup.</div></div><div className="mt-8 flex gap-3"><Button variant="outline" onClick={() => setSetupStep(0)}>Back</Button><Button className="bg-coral text-white" disabled={!setupName.trim()} onClick={() => setSetupStep(2)}>Continue</Button></div></> : <form onSubmit={submitSetup}><p className="eyebrow">Step 03 / 03</p><h1 className="mt-3 font-display text-4xl font-semibold">Meet your first admin.</h1><p className="mt-3 text-[#637569]">Create a unique password of at least 12 characters. It is never sent by email.</p><div className="mt-8 grid gap-5"><Field label="Your name"><Input required maxLength={100} value={setupAdmin.name} onChange={e=>setSetupAdmin({...setupAdmin,name:e.target.value})} /></Field><Field label="Email address"><Input required type="email" value={setupAdmin.email} onChange={e=>setSetupAdmin({...setupAdmin,email:e.target.value})} /></Field><Field label="Password"><Input required type="password" minLength={12} maxLength={128} autoComplete="new-password" value={setupAdmin.password} onChange={e=>setSetupAdmin({...setupAdmin,password:e.target.value})} /></Field></div><div className="mt-8 flex gap-3"><Button type="button" variant="outline" onClick={() => setSetupStep(1)}>Back</Button><Button type="submit" disabled={busy} className="bg-coral text-white">Create organization</Button></div></form>}</div></div></main>;
  return <div className="min-h-screen bg-cream text-forest"><header className="sticky top-0 z-40 border-b border-[#e6e9dd] bg-cream/95 backdrop-blur"><div className="mx-auto flex h-20 max-w-7xl items-center justify-between gap-4 px-5 lg:px-8"><button className="flex items-center gap-3 text-left" onClick={() => navigate('home')}>{bootstrap.settings.logo ? <img src={bootstrap.settings.logo} className="h-11 w-11 rounded-xl object-contain" alt="" /> : <BrandMark />}<span className="font-display text-xl font-bold tracking-tight sm:text-2xl">{bootstrap.settings.name}</span></button><nav className="hidden items-center gap-1 md:flex" aria-label="Main navigation">{([['home','Home'],['events','Find an event'],...(bootstrap.user ? [['portal','My impact']] : []),...(staff ? [['staff','Administration']] : [])] as [typeof page,string][]).map(([key,label])=><button key={key} onClick={() => navigate(key)} className={`rounded-full px-4 py-2 text-sm font-semibold transition-colors ${page===key?'bg-[#e4ede3] text-forest':'text-[#53695b] hover:bg-[#eef2e9]'}`}>{label}</button>)}</nav><div className="hidden items-center gap-3 md:flex">{bootstrap.user ? <><span className="text-sm text-[#627468]">Hi, {bootstrap.user.name.split(' ')[0]}</span><Button variant="ghost" size="icon" aria-label="Sign out" onClick={() => void act(() => request('/api/logout',{}), 'Signed out.')}><LogOut size={18}/></Button></> : <><button className="text-sm font-semibold" onClick={() => setAuth('login')}>Log in</button><Button onClick={() => setAuth('register')} className="rounded-full bg-forest px-5 text-white hover:bg-[#306452]">Join our community <ArrowRight size={15} className="ml-2" /></Button></>}</div><button aria-label="Open menu" className="md:hidden" onClick={() => setMobileOpen(!mobileOpen)}>{mobileOpen ? <X/> : <Menu/>}</button></div>{mobileOpen && <nav className="space-y-1 border-t border-[#e6e9dd] px-5 py-4 md:hidden">{([['home','Home'],['events','Find an event'],...(bootstrap.user ? [['portal','My impact']] : []),...(staff ? [['staff','Administration']] : [])] as [typeof page,string][]).map(([key,label])=><button key={key} onClick={() => navigate(key)} className="block w-full rounded-xl px-4 py-3 text-left text-sm font-semibold hover:bg-white">{label}</button>)}<button className="block w-full px-4 py-3 text-left text-sm font-semibold" onClick={() => { setMobileOpen(false); bootstrap.user ? void act(() => request('/api/logout',{}), 'Signed out.') : setAuth('login'); }}>{bootstrap.user ? 'Sign out':'Log in'}</button></nav>}</header>
  {offline && <div role="alert" className="bg-[#fff0da] px-5 py-3 text-center text-sm font-semibold text-[#77501b]">The application server is unavailable. This page is a preview only; sign-in and registrations require the self-hosted server. <button className="underline" onClick={() => void refresh()}>Try again</button></div>}
  {page === 'home' && <><section className="relative overflow-hidden bg-[#e9efe5]"><div className="absolute inset-y-0 right-0 hidden w-[55%] lg:block"><img src="/assets/community-garden.png" alt="Neighbors volunteering together in a community garden" className="h-full w-full object-cover object-center" /><div className="absolute inset-y-0 left-0 w-20 bg-[#e9efe5] [mask-image:linear-gradient(to_right,black,transparent)]" /></div><div className="relative mx-auto grid max-w-7xl lg:grid-cols-2"><div className="px-6 py-16 sm:px-10 sm:py-24 lg:py-32"><span className="inline-flex items-center gap-2 rounded-full bg-white px-4 py-2 text-xs font-bold uppercase tracking-[.14em] text-[#406b56]"><span className="h-2 w-2 rounded-full bg-coral" /> Small acts. Lasting impact.</span><h1 className="mt-8 max-w-xl font-display text-5xl font-semibold leading-[1.05] tracking-tight sm:text-6xl lg:text-7xl">Good things grow <em className="font-normal text-coral">together.</em></h1><p className="mt-7 max-w-lg text-lg leading-8 text-[#566e5e]">Find meaningful ways to give your time, connect with neighbors, and see the difference you make—one hour at a time.</p><div className="mt-9 flex flex-wrap gap-3"><Button size="lg" className="rounded-full bg-coral px-7 text-white hover:bg-[#bd4d39]" onClick={() => navigate('events')}>Explore opportunities <ArrowRight className="ml-2 h-5 w-5" /></Button><Button size="lg" variant="outline" className="rounded-full border-[#b5c7b5] bg-transparent px-7 text-forest" onClick={() => bootstrap.user ? navigate('portal') : setAuth('register')}>See your impact</Button></div><div className="mt-14 flex flex-wrap items-center gap-6 border-t border-[#cbd8c9] pt-6 text-sm font-medium text-[#486550]"><span className="flex items-center gap-2"><Heart className="h-5 w-5 text-coral"/> Real connection</span><span className="flex items-center gap-2"><ShieldCheck className="h-5 w-5 text-coral"/> Every hour counts</span></div></div><div className="lg:hidden"><img src="/assets/community-garden.png" alt="Neighbors volunteering in a garden" className="h-72 w-full object-cover" /></div></div></section><section className="mx-auto max-w-7xl px-5 py-16 lg:px-8 lg:py-24"><div className="mb-9 flex flex-wrap items-end justify-between gap-5"><div><p className="eyebrow">Find your place</p><h2 className="mt-3 font-display text-4xl font-semibold sm:text-5xl">Upcoming opportunities<span className="text-coral">.</span></h2><p className="mt-3 text-[#667769]">There's room for everyone to make a difference.</p></div><button className="flex items-center gap-2 font-semibold text-coral" onClick={() => navigate('events')}>View all events <ArrowRight size={18}/></button></div>{bootstrap.events.length ? <div className="grid gap-6 md:grid-cols-2 xl:grid-cols-3">{bootstrap.events.slice(0,3).map(eventCard)}</div> : <EmptyEvents isStaff={!!staff} openStaff={() => { navigate('staff'); setStaffTab('events'); }} />}</section><section className="bg-forest px-5 py-16 text-white lg:py-24"><div className="mx-auto grid max-w-7xl gap-10 lg:grid-cols-[1fr_1.1fr] lg:items-center"><div><p className="text-xs font-bold uppercase tracking-[.2em] text-[#edb29f]">Why volunteer with us</p><h2 className="mt-4 font-display text-4xl font-semibold leading-tight sm:text-5xl">Your time has a story. <em className="font-normal text-[#edb29f]">Let's tell it.</em></h2><p className="mt-5 max-w-xl leading-8 text-[#d2e3d7]">From your first event to your next milestone, keep all the moments that matter in one welcoming place.</p></div><div className="grid gap-4 sm:grid-cols-3">{[[<CalendarDays key="i"/>, 'Show up', 'Find an event that fits your schedule.'],[<Clock3 key="i"/>, 'Track time', 'See your verified hours add up.'],[<Medal key="i"/>, 'Grow together', 'Celebrate every milestone earned.']].map(([icon,title,desc])=><div key={String(title)} className="rounded-3xl bg-white/10 p-6"><span className="mb-6 flex h-11 w-11 items-center justify-center rounded-xl bg-white/15 text-[#edb29f]">{icon}</span><h3 className="font-display text-xl font-semibold">{title}</h3><p className="mt-2 text-sm leading-6 text-[#d2e3d7]">{desc}</p></div>)}</div></div></section></>}
  {page === 'events' && <main className="mx-auto max-w-7xl px-5 py-12 lg:px-8 lg:py-20"><p className="eyebrow">Opportunities</p><h1 className="mt-3 font-display text-5xl font-semibold">Find your next good thing.</h1><p className="mb-10 mt-4 max-w-2xl leading-7 text-[#667769]">Browse upcoming events, find a place that feels right, and save your spot. Event times are shown in the event's local time zone.</p>{bootstrap.events.length ? <div className="grid gap-6 md:grid-cols-2 xl:grid-cols-3">{bootstrap.events.map(eventCard)}</div> : <EmptyEvents isStaff={!!staff} openStaff={() => { navigate('staff'); setStaffTab('events'); }} />}</main>}
  {page === 'portal' && <main className="mx-auto max-w-7xl px-5 py-12 lg:px-8 lg:py-20">{!member ? <div className="rounded-3xl bg-white p-10 text-center"><h1 className="font-display text-4xl">Your impact starts here.</h1><p className="mt-3 text-[#667769]">Sign in to see your hours, events, and milestones.</p><Button onClick={() => setAuth('login')} className="mt-6 rounded-full bg-coral text-white">Log in</Button></div> : <><p className="eyebrow">Your volunteer home</p><h1 className="mt-3 font-display text-4xl font-semibold sm:text-5xl">Hello, {member.user.name.split(' ')[0]} <span className="text-coral">✳</span></h1><p className="mt-3 text-[#667769]">Every moment you give makes a difference. Here's yours so far.</p><div className="mt-9 grid gap-4 sm:grid-cols-3">{[[<Clock3 key="a"/>, `${member.metrics.hours}`, 'Verified hours'],[<CalendarDays key="b"/>, `${member.metrics.events}`, 'Events completed'],[<Medal key="c"/>, `${member.milestones.filter(m => member.metrics[m.metric] >= m.threshold).length}`, 'Medals earned']].map(([icon,num,label])=><div key={String(label)} className="rounded-3xl border border-[#e7e9db] bg-white p-7"><span className="flex h-12 w-12 items-center justify-center rounded-2xl bg-[#fbe8e1] text-coral">{icon}</span><div className="mt-5 font-display text-4xl font-semibold">{num}</div><p className="mt-1 text-sm text-[#627468]">{label}</p></div>)}</div><section className="panel mt-8"><h2 className="section-title mb-4">Your attendance QR</h2><AttendanceQr onUpdate={refresh} /></section><div className="mt-8 grid gap-6 lg:grid-cols-[1.35fr_1fr]"><div className="space-y-6"><section className="panel"><div className="flex items-center justify-between"><h2 className="section-title">Your registrations</h2><button className="text-sm font-semibold text-coral" onClick={() => navigate('events')}>Explore events →</button></div>{member.registrations.length ? <div className="mt-5 divide-y divide-[#e8ebe2]">{member.registrations.map(e=><div key={e.id} className="flex flex-wrap items-center justify-between gap-4 py-4"><div><p className="font-semibold">{e.title}</p><p className="mt-1 text-sm text-[#667769]">{dateLabel(e.starts_at,e.timezone)} · {e.location}</p></div><Button size="sm" variant="outline" disabled={busy} className="rounded-full" onClick={() => void act(() => request(`/api/registrations/${e.id}`, undefined, 'DELETE'), 'Registration canceled.')}>Cancel</Button></div>)}</div> : <p className="mt-5 text-sm text-[#667769]">No registrations yet. Your next opportunity is waiting.</p>}</section><section className="panel"><h2 className="section-title">Attendance history</h2>{member.attendance.length ? <div className="mt-5 divide-y divide-[#e8ebe2]">{member.attendance.map(a=><div key={a.event_id} className="flex items-center justify-between gap-3 py-4"><div><p className="font-semibold">{a.title}</p><p className="text-sm text-[#667769]">{dateLabel(a.check_in)} · {a.method}</p></div><span className="rounded-full bg-[#e8f2e9] px-3 py-1 text-xs font-semibold">{a.check_out ? `${Math.max(0,(Date.parse(a.check_out)-Date.parse(a.check_in))/3600000).toFixed(1)} hrs` : 'Checked in'}</span></div>)}</div> : <p className="mt-5 text-sm text-[#667769]">Your completed events will appear here.</p>}</section></div><div className="space-y-6"><section className="panel"><div className="flex items-center gap-2"><Medal size={21} className="text-coral"/><h2 className="section-title">Milestones</h2></div>{member.milestones.length ? <div className="mt-6 space-y-6">{member.milestones.map(m=>{ const value = member.metrics[m.metric]; return <div key={m.id}><div className="mb-2 flex items-center justify-between gap-3"><span className="font-semibold">{value >= m.threshold ? '🏅 ' : '✳ '}{m.name}</span><span className="text-xs text-[#667769]">{Math.min(value,m.threshold)} / {m.threshold} {m.metric}</span></div><Progress value={Math.min(100,value/m.threshold*100)} className="h-2 bg-[#e9efe6] [&>div]:bg-coral" /></div>; })}</div> : <p className="mt-5 text-sm text-[#667769]">Your organization has not added milestones yet.</p>}</section><section className="panel"><h2 className="section-title">Your profile</h2><p className="mt-2 text-sm text-[#667769]">{member.user.email} · {member.user.role}</p><form className="mt-5 flex gap-2" onSubmit={e=>{e.preventDefault(); const name = String(new FormData(e.currentTarget).get('name')); void act(() => request('/api/profile',{name}), 'Profile updated.');}}><Input name="name" defaultValue={member.user.name} aria-label="Your name" maxLength={100} required className="rounded-xl"/><Button type="submit" className="rounded-xl bg-forest text-white">Save</Button></form></section>{bootstrap.waiver && <section className="panel"><div className="flex gap-3"><ShieldCheck className="shrink-0 text-coral"/><div><h2 className="section-title">Volunteer waiver · v{bootstrap.waiver.version}</h2><p className="mt-2 whitespace-pre-wrap text-sm leading-6 text-[#627468]">{bootstrap.waiver.text}</p></div></div>{bootstrap.waiver.signed ? <p className="mt-5 flex items-center gap-2 font-semibold text-[#387153]"><Check size={18}/> Signed and on file</p> : <form className="mt-5 space-y-3" onSubmit={e=>{e.preventDefault(); void act(() => request('/api/waiver/sign',{name:signature}), 'Waiver signed.');}}><Label htmlFor="signature">Type your full name to sign</Label><Input id="signature" required value={signature} onChange={e=>setSignature(e.target.value)} placeholder={member.user.name} /><Button className="rounded-full bg-coral text-white">Sign waiver</Button></form>}</section>}</div></div></>}</main>}
  {page === 'staff' && <main className="mx-auto max-w-7xl px-5 py-12 lg:px-8 lg:py-20">{!staff ? <p className="text-center">Staff access required.</p> : <><p className="eyebrow">Make good things happen</p><h1 className="mt-3 font-display text-4xl font-semibold sm:text-5xl">Organization desk<span className="text-coral">.</span></h1><p className="mt-3 text-[#667769]">Your space to support the people behind every hour.</p><div className="mt-9 flex gap-2 overflow-x-auto pb-3">{([['overview','Overview'],['events','Events'],['attendance','Attendance'],['members','Members'],...(bootstrap.user?.role === 'admin' ? [['waivers','Waivers'],['medals','Medals'],['settings','Settings']] : [])] as [typeof staffTab,string][]).map(([key,label])=><button key={key} onClick={()=>setStaffTab(key)} className={`whitespace-nowrap rounded-full px-5 py-2.5 text-sm font-semibold ${staffTab===key?'bg-forest text-white':'border border-[#dce4d8] bg-white text-[#526758]'}`}>{label}</button>)}</div>
    {staffTab === 'overview' && <><div className="mt-6 grid gap-4 sm:grid-cols-3">{[[<Users key="a"/>,staff.members.length,'Members'],[<CalendarDays key="b"/>,staff.events.filter(e=>!e.canceled).length,'Events'],[<Clock3 key="c"/>,staff.attendance.length,'Check-ins']].map(([icon,num,label])=><div key={String(label)} className="panel"><div className="text-coral">{icon}</div><div className="mt-4 font-display text-4xl font-semibold">{num}</div><p className="text-sm text-[#667769]">{label}</p></div>)}</div><div className="panel mt-6"><h2 className="section-title">Quick actions</h2><div className="mt-5 flex flex-wrap gap-3"><Button className="rounded-full bg-coral text-white" onClick={()=>setStaffTab('events')}><Plus size={17} className="mr-2"/> Create event</Button><Button variant="outline" className="rounded-full" onClick={()=>setStaffTab('attendance')}>Record attendance</Button><a className="inline-flex items-center gap-2 rounded-full border px-4 py-2 text-sm font-medium" href="/api/staff/export/members"><Download size={16}/> Export members</a><a className="inline-flex items-center gap-2 rounded-full border px-4 py-2 text-sm font-medium" href="/api/staff/export/attendance"><Download size={16}/> Export attendance</a></div></div></>}
    {staffTab === 'events' && <div className="mt-6 grid gap-6 xl:grid-cols-[.9fr_1.1fr]"><form className="panel h-fit space-y-5" onSubmit={e=>{ e.preventDefault(); void act(() => request('/api/staff/events',{...eventForm, capacity:Number(eventForm.capacity), count:Number(eventForm.count)}), 'Event created.'); }}><div className="flex items-center gap-2"><Plus className="text-coral"/><h2 className="section-title">Create an event</h2></div><Field label="Event title"><Input required maxLength={120} value={eventForm.title} onChange={e=>setEventForm({...eventForm,title:e.target.value})}/></Field><Field label="Description"><Textarea required maxLength={4000} value={eventForm.description} onChange={e=>setEventForm({...eventForm,description:e.target.value})}/></Field><Field label="Location"><Input required maxLength={250} value={eventForm.location} onChange={e=>setEventForm({...eventForm,location:e.target.value})}/></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Starts"><Input required type="datetime-local" value={eventForm.startsAt} onChange={e=>setEventForm({...eventForm,startsAt:e.target.value})}/></Field><Field label="Ends"><Input required type="datetime-local" value={eventForm.endsAt} onChange={e=>setEventForm({...eventForm,endsAt:e.target.value})}/></Field></div><p className="text-xs leading-5 text-[#667769]">Enter times in the selected event time zone. Recurrences stay at the same local time through daylight-saving changes.</p><Field label="Event time zone (IANA)"><Input required value={eventForm.timezone} onChange={e=>setEventForm({...eventForm,timezone:e.target.value})} placeholder="America/New_York" /></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Capacity"><Input type="number" min="1" max="100000" required value={eventForm.capacity} onChange={e=>setEventForm({...eventForm,capacity:e.target.value})}/></Field><Field label="Visibility"><Select value={eventForm.visibility} onValueChange={visibility=>setEventForm({...eventForm,visibility})}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="public">Public</SelectItem><SelectItem value="private">Signed-in members</SelectItem></SelectContent></Select></Field></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Repeat"><Select value={eventForm.frequency} onValueChange={frequency=>setEventForm({...eventForm,frequency})}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{['none','daily','weekly','monthly'].map(v=><SelectItem key={v} value={v}>{v === 'none' ? 'Does not repeat' : v[0].toUpperCase()+v.slice(1)}</SelectItem>)}</SelectContent></Select></Field>{eventForm.frequency !== 'none' && <Field label="Occurrences (including first)"><Input type="number" min="1" max="52" value={eventForm.count} onChange={e=>setEventForm({...eventForm,count:e.target.value})}/></Field>}</div><Button type="submit" disabled={busy} className="w-full rounded-full bg-coral text-white">Publish event <ArrowRight size={16} className="ml-2"/></Button></form><section className="panel"><h2 className="section-title">All events</h2><div className="mt-5 max-h-[700px] divide-y divide-[#e8ebe2] overflow-y-auto">{staff.events.length ? staff.events.map(e=><div key={e.id} className="flex items-center justify-between gap-3 py-4"><div><p className="font-semibold">{e.title} {e.canceled ? <span className="text-xs text-coral">· Canceled</span> : ''}</p><p className="mt-1 text-xs text-[#667769]">{dateLabel(e.starts_at,e.timezone)} · {e.visibility} · #{e.series_id}</p></div><Button size="sm" variant="outline" className="rounded-full" onClick={()=>showEdit(e)}>Manage</Button></div>) : <p className="text-sm text-[#667769]">Create your first event to get started.</p>}</div></section></div>}
    {staffTab === 'attendance' && <div className="mt-6 grid gap-6 lg:grid-cols-[.8fr_1.2fr]"><form className="panel h-fit space-y-5" onSubmit={e=>{e.preventDefault(); void act(() => request('/api/staff/attendance',{...attendanceForm,eventId:Number(attendanceForm.eventId),userId:Number(attendanceForm.userId)}), attendanceForm.action==='in'?'Member checked in.':'Member checked out.');}}><h2 className="section-title">Record attendance</h2><p className="text-sm text-[#667769]">Assist a registered member or record a walk-in. Check-out calculates verified hours.</p><Field label="Event"><Select value={attendanceForm.eventId} onValueChange={eventId=>setAttendanceForm({...attendanceForm,eventId})}><SelectTrigger><SelectValue placeholder="Select event"/></SelectTrigger><SelectContent>{staff.events.filter(e=>!e.canceled).map(e=><SelectItem key={e.id} value={String(e.id)}>{e.title} · {dateLabel(e.starts_at)}</SelectItem>)}</SelectContent></Select></Field><Field label="Member"><Select value={attendanceForm.userId} onValueChange={userId=>setAttendanceForm({...attendanceForm,userId})}><SelectTrigger><SelectValue placeholder="Select member"/></SelectTrigger><SelectContent>{staff.members.map(m=><SelectItem key={m.id} value={String(m.id)}>{m.name} · {m.email}</SelectItem>)}</SelectContent></Select></Field><Field label="Action"><Select value={attendanceForm.action} onValueChange={action=>setAttendanceForm({...attendanceForm,action})}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="in">Check in</SelectItem><SelectItem value="out">Check out</SelectItem></SelectContent></Select></Field>{attendanceForm.action==='in' && <Field label="Attendance type"><Select value={attendanceForm.method} onValueChange={method=>setAttendanceForm({...attendanceForm,method})}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="staff">Staff assisted</SelectItem><SelectItem value="walk-in">Walk-in</SelectItem></SelectContent></Select></Field>}<Button disabled={busy || !attendanceForm.eventId || !attendanceForm.userId} className="w-full rounded-full bg-coral text-white">Record {attendanceForm.action==='in'?'check-in':'check-out'}</Button></form><section className="panel"><h2 className="section-title mb-4">QR attendance</h2><AttendanceQr staff eventId={attendanceForm.eventId} onUpdate={refresh} /><h2 className="section-title mt-8">Recent attendance</h2><div className="mt-5 max-h-[650px] divide-y divide-[#e8ebe2] overflow-y-auto">{staff.attendance.length ? staff.attendance.map(a=><div key={`${a.event_id}-${a.user_id}`} className="flex justify-between gap-4 py-4"><div><p className="font-semibold">{a.name}</p><p className="text-sm text-[#667769]">{a.title} · {a.method}</p><p className="mt-1 text-xs text-[#667769]">In: {dateLabel(a.check_in)}{a.check_out && ` · Out: ${dateLabel(a.check_out)}`}</p></div><span className="shrink-0 text-sm font-semibold text-coral">{a.check_out ? `${Math.max(0,(Date.parse(a.check_out)-Date.parse(a.check_in))/3600000).toFixed(1)} hrs`:'Active'}</span></div>) : <p className="text-sm text-[#667769]">No attendance recorded yet.</p>}</div></section></div>}
    {staffTab === 'members' && <section className="panel mt-6"><div className="flex flex-wrap items-center justify-between gap-3"><h2 className="section-title">Members · {staff.members.length}</h2><a href="/api/staff/export/members" className="flex items-center gap-2 text-sm font-semibold text-coral"><Download size={16}/> Download CSV</a></div><div className="mt-5 divide-y divide-[#e8ebe2]">{staff.members.map(m=><div key={m.id} className="flex flex-wrap items-center justify-between gap-3 py-4"><div><p className="font-semibold">{m.name}</p><p className="text-sm text-[#667769]">{m.email}</p></div>{bootstrap.user?.role === 'admin' ? <Select value={m.role} onValueChange={role=>void act(() => request('/api/staff/role',{userId:m.id,role}), 'Role updated.')}><SelectTrigger className="w-36 rounded-xl"><SelectValue/></SelectTrigger><SelectContent>{['member','assistant','admin'].map(r=><SelectItem key={r} value={r}>{r}</SelectItem>)}</SelectContent></Select> : <span className="capitalize text-sm text-[#667769]">{m.role}</span>}</div>)}</div></section>}
    {staffTab === 'waivers' && <div className="mt-6 grid gap-6 lg:grid-cols-2"><form className="panel h-fit space-y-5" onSubmit={e=>{e.preventDefault(); void act(() => request('/api/staff/waivers',{text:waiverText}), 'New waiver version published.');}}><h2 className="section-title">Publish a new waiver</h2><p className="text-sm text-[#667769]">Changes create a new version. Members' previous signatures are preserved.</p><Textarea required rows={12} maxLength={20000} value={waiverText} onChange={e=>setWaiverText(e.target.value)} placeholder="Write your volunteer waiver here..."/><Button disabled={busy} className="rounded-full bg-coral text-white">Publish version</Button></form><section className="panel"><h2 className="section-title">Version history</h2>{staff.waivers.map(w=><div key={w.id} className="mt-5 rounded-2xl bg-[#f4f5ef] p-5"><p className="font-semibold">Version {w.version}</p><p className="mt-3 whitespace-pre-wrap text-sm text-[#627468]">{w.text}</p></div>)}</section></div>}
    {staffTab === 'medals' && <div className="mt-6 grid gap-6 lg:grid-cols-2"><form className="panel h-fit space-y-5" onSubmit={e=>{e.preventDefault(); void act(() => request('/api/staff/medals',{...medalForm,threshold:Number(medalForm.threshold)}), 'Milestone added.');}}><h2 className="section-title">Create a milestone</h2><Field label="Medal name"><Input required maxLength={100} value={medalForm.name} onChange={e=>setMedalForm({...medalForm,name:e.target.value})} placeholder="Community Champion"/></Field><Field label="Based on"><Select value={medalForm.metric} onValueChange={metric=>setMedalForm({...medalForm,metric})}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="events">Completed events</SelectItem><SelectItem value="hours">Verified hours</SelectItem></SelectContent></Select></Field><Field label="Threshold"><Input type="number" min="1" required value={medalForm.threshold} onChange={e=>setMedalForm({...medalForm,threshold:e.target.value})}/></Field><Button disabled={busy} className="rounded-full bg-coral text-white">Create medal</Button></form><section className="panel"><h2 className="section-title">Available medals</h2>{staff.medals.map(m=><div key={m.id} className="flex items-center justify-between border-b border-[#e8ebe2] py-4"><span className="flex items-center gap-3 font-semibold"><Medal className="text-coral"/>{m.name} <span className="text-xs font-normal text-[#667769]">{m.threshold} {m.metric}</span></span><Button variant="ghost" size="sm" onClick={()=>void act(() => request(`/api/staff/medals/${m.id}`,undefined,'DELETE'), 'Medal removed.')}>Remove</Button></div>)}</section></div>}
    {staffTab === 'settings' && <form className="panel mt-6 max-w-3xl space-y-5" onSubmit={e=>{e.preventDefault(); void act(() => request('/api/staff/settings',settingsForm), 'Settings saved.');}}><div className="flex items-center gap-2"><Settings2 className="text-coral"/><h2 className="section-title">Organization settings</h2></div><Field label="Organization name"><Input required value={settingsForm.name} onChange={e=>setSettingsForm({...settingsForm,name:e.target.value})}/></Field><Field label="Brand color"><div className="flex gap-3"><Input type="color" className="h-10 w-16 p-1" value={settingsForm.color} onChange={e=>setSettingsForm({...settingsForm,color:e.target.value})}/><Input required value={settingsForm.color} onChange={e=>setSettingsForm({...settingsForm,color:e.target.value})}/></div></Field><Field label="Logo (PNG, JPEG, WebP; up to 2 MB)"><Input type="file" accept="image/png,image/jpeg,image/webp" onChange={async e=>{const file=e.target.files?.[0]; if (!file) return; if (file.size>2000000) { toast.error('Logo must be under 2 MB.'); return; } const reader = new FileReader(); reader.onload = () => {const base64 = String(reader.result).split(',')[1]; void act(() => request('/api/staff/logo',{type:file.type,base64}), 'Logo updated.');}; reader.readAsDataURL(file);}} /></Field><div className="border-t pt-5"><h3 className="font-display text-xl font-semibold">Email delivery</h3><p className="mt-2 text-sm text-[#667769]">File mode saves private messages in the persistent assets volume. Console mode logs delivery notices only (not account links).</p></div><Field label="Delivery mode"><Select value={settingsForm.mailMode} onValueChange={mailMode=>setSettingsForm({...settingsForm,mailMode})}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="file">Private files (default)</SelectItem><SelectItem value="console">Console notices only</SelectItem><SelectItem value="smtp">SMTP server</SelectItem></SelectContent></Select></Field>{settingsForm.mailMode==='smtp' && <div className="grid gap-4 sm:grid-cols-2"><Field label="SMTP host"><Input required value={settingsForm.smtpHost} onChange={e=>setSettingsForm({...settingsForm,smtpHost:e.target.value})}/></Field><Field label="Port"><Input required type="number" min="1" max="65535" value={settingsForm.smtpPort} onChange={e=>setSettingsForm({...settingsForm,smtpPort:e.target.value})}/></Field><Field label="Encryption"><Select value={settingsForm.smtpEncryption} onValueChange={smtpEncryption=>setSettingsForm({...settingsForm,smtpEncryption})}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="starttls">STARTTLS</SelectItem><SelectItem value="tls">Implicit TLS</SelectItem></SelectContent></Select></Field><Field label="Username"><Input value={settingsForm.smtpUser} onChange={e=>setSettingsForm({...settingsForm,smtpUser:e.target.value})}/></Field><Field label="Password"><Input type="password" autoComplete="new-password" value={settingsForm.smtpPassword} onChange={e=>setSettingsForm({...settingsForm,smtpPassword:e.target.value})} placeholder="Leave blank to keep existing"/></Field><Field label="Sender address"><Input required type="email" value={settingsForm.smtpFrom} onChange={e=>setSettingsForm({...settingsForm,smtpFrom:e.target.value})}/></Field></div>}<div className="flex flex-wrap gap-3"><Button disabled={busy} className="rounded-full bg-coral text-white">Save settings</Button><Button type="button" variant="outline" disabled={busy} className="rounded-full" onClick={()=>void act(() => request('/api/staff/test-email',{}), 'Test email queued. Check your selected delivery destination.')}>Send test email</Button></div></form>}
  </>}</main>}
  <footer className="border-t border-[#e2e8dd] bg-[#edf1e9] px-5 py-10"><div className="mx-auto flex max-w-7xl flex-wrap items-center justify-between gap-4"><div className="flex items-center gap-3"><BrandMark/><div><p className="font-display text-lg font-bold">{bootstrap.settings.name}</p><p className="text-xs text-[#64776a]">Good things grow together.</p></div></div><span className="text-sm text-[#64776a]">Made for the moments that matter. <Heart size={14} className="inline text-coral"/></span></div></footer>
  <Dialog open={!!auth} onOpenChange={open=>{if (!open) setAuth(null);}}><DialogContent className="max-w-md rounded-[28px] border-[#e5e9df] p-8"><DialogHeader><div className="mb-4 flex h-12 w-12 items-center justify-center rounded-2xl bg-[#fbe9e2] text-coral"><Heart size={24}/></div><DialogTitle className="font-display text-3xl text-forest">{auth==='register'?'Join the community':auth==='forgot'?'Reset your password':auth==='password'?'Choose your password':'Welcome back'}</DialogTitle></DialogHeader><p className="text-sm leading-6 text-[#65776b]">{auth==='register'?'We’ll email you a private setup link.':auth==='forgot'?'If this email has an account, we’ll send a reset link.':auth==='password'?'Your link expires after 30 minutes and can only be used once.':'Sign in to see the good you’re doing.'}</p><form onSubmit={submitAuth} className="mt-4 space-y-4">{auth==='register' && <Field label="Full name"><Input required maxLength={100} autoComplete="name" value={authForm.name} onChange={e=>setAuthForm({...authForm,name:e.target.value})}/></Field>}{auth!=='password' && <Field label="Email address"><Input required type="email" autoComplete="email" value={authForm.email} onChange={e=>setAuthForm({...authForm,email:e.target.value})}/></Field>}{['login','password'].includes(auth || '') && <Field label="Password"><Input required type="password" minLength={auth==='password'?12:undefined} maxLength={128} autoComplete={auth==='password'?'new-password':'current-password'} value={authForm.password} onChange={e=>setAuthForm({...authForm,password:e.target.value})}/></Field>}<Button disabled={busy} className="w-full rounded-full bg-coral text-white hover:bg-[#bd4d39]">{auth==='login'?'Log in':auth==='password'?'Set password':'Continue'} <ArrowRight size={16} className="ml-2"/></Button></form>{auth==='login' && <button className="mt-4 text-sm font-semibold text-coral" onClick={()=>setAuth('forgot')}>Forgot your password?</button>}<div className="mt-5 border-t pt-5 text-sm text-[#65776b]">{auth==='register'?'Already a member?':'New around here?'} <button className="font-semibold text-coral" onClick={()=>setAuth(auth==='register'?'login':'register')}>{auth==='register'?'Log in':'Create an account'}</button></div></DialogContent></Dialog>
  <Dialog open={!!editEvent} onOpenChange={open=>{if(!open)setEditEvent(null);}}><DialogContent className="max-h-[90vh] max-w-lg overflow-y-auto rounded-[28px] p-7"><DialogHeader><DialogTitle className="font-display text-2xl">Manage event</DialogTitle></DialogHeader>{editEvent && <form className="space-y-4" onSubmit={e=>{e.preventDefault(); void act(async () => { await request(`/api/staff/events/${editEvent.id}`,{...editForm,capacity:Number(editForm.capacity),starts_at:editForm.starts_at,ends_at:editForm.ends_at},'PATCH'); setEditEvent(null); }, 'Event updated.');}}><Field label="Title"><Input required value={editForm.title} onChange={e=>setEditForm({...editForm,title:e.target.value})}/></Field><Field label="Description"><Textarea required value={editForm.description} onChange={e=>setEditForm({...editForm,description:e.target.value})}/></Field><Field label="Location"><Input required value={editForm.location} onChange={e=>setEditForm({...editForm,location:e.target.value})}/></Field><div className="grid grid-cols-2 gap-3"><Field label="Starts"><Input type="datetime-local" required value={editForm.starts_at} onChange={e=>setEditForm({...editForm,starts_at:e.target.value})}/></Field><Field label="Ends"><Input type="datetime-local" required value={editForm.ends_at} onChange={e=>setEditForm({...editForm,ends_at:e.target.value})}/></Field></div><Field label="Capacity"><Input type="number" min="1" required value={editForm.capacity} onChange={e=>setEditForm({...editForm,capacity:e.target.value})}/></Field><Field label="Visibility"><Select value={editForm.visibility} onValueChange={visibility=>setEditForm({...editForm,visibility})}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="public">Public</SelectItem><SelectItem value="private">Signed-in members</SelectItem></SelectContent></Select></Field><Field label="Apply to"><Select value={editForm.scope} onValueChange={scope=>setEditForm({...editForm,scope})}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="single">This occurrence only</SelectItem><SelectItem value="series">Entire series</SelectItem></SelectContent></Select></Field><div className="flex flex-wrap gap-3"><Button type="submit" disabled={busy} className="rounded-full bg-coral text-white">Save changes</Button><Button type="button" variant="outline" disabled={busy || !!editEvent.canceled} className="rounded-full text-[#a33c32]" onClick={()=>{if(window.confirm(`Cancel ${editForm.scope==='series'?'the entire series':'this occurrence'}?`)) void act(async ()=>{await request(`/api/staff/events/${editEvent.id}`,{scope:editForm.scope,canceled:1},'PATCH');setEditEvent(null);},'Event canceled.');}}>Cancel event</Button></div></form>}</DialogContent></Dialog>
  </div>;
}
function BrandMark(){return <span aria-hidden="true" className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl bg-coral text-white"><Leaf size={25} strokeWidth={2.5}/></span>}
function EmptyEvents({isStaff,openStaff}:{isStaff:boolean;openStaff:()=>void}){return <div className="rounded-[30px] border border-dashed border-[#b8cbb6] bg-white px-6 py-16 text-center"><span className="mx-auto flex h-16 w-16 items-center justify-center rounded-3xl bg-[#e5efe4] text-coral"><Sparkles size={30}/></span><h3 className="mt-5 font-display text-2xl font-semibold">Good things are on the way.</h3><p className="mx-auto mt-2 max-w-md text-sm leading-6 text-[#667769]">There aren't any upcoming events yet. Check back soon for opportunities to get involved.</p>{isStaff && <Button className="mt-6 rounded-full bg-coral text-white" onClick={openStaff}>Create an event <ChevronRight size={16} className="ml-1"/></Button>}</div>}
